#!/usr/bin/env python3
from pathlib import Path
import sys

root = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path('build/PrePoMax-CodeAster').resolve()
path = root / 'PrePoMax' / 'CodeAster' / 'CodeAsterResultsDemo.cs'
text = path.read_text(encoding='utf-8')

anchor = '''                controller.ViewResultsType = ViewResultsTypeEnum.ColorContours;\n                controller.DrawResults(false);\n                Application.DoEvents();\n\n                NativeScalarBarGate.Report scalarBarReport = NativeScalarBarGate.Verify(controller, min, max);\n'''
insert = '''                controller.ViewResultsType = ViewResultsTypeEnum.ColorContours;\n                controller.DrawResults(false);\n                Application.DoEvents();\n\n                // C8.71: qualify native deformation geometry against solver-admitted displacement components.\n                // This tests the same Controller.GetScaledNode(scale,nodeId) path used by native annotations/query geometry.\n                FieldData dispU1Data = new FieldData(FOFieldNames.Disp, FOComponentNames.U1, 1, 1);\n                FieldData dispU2Data = new FieldData(FOFieldNames.Disp, FOComponentNames.U2, 1, 1);\n                FieldData dispU3Data = new FieldData(FOFieldNames.Disp, FOComponentNames.U3, 1, 1);\n                float[] probeU1Values = results.GetValues(dispU1Data, new int[] { verifiedDispNode });\n                float[] probeU2Values = results.GetValues(dispU2Data, new int[] { verifiedDispNode });\n                float[] probeU3Values = results.GetValues(dispU3Data, new int[] { verifiedDispNode });\n                if (probeU1Values == null || probeU1Values.Length != 1 ||\n                    probeU2Values == null || probeU2Values.Length != 1 ||\n                    probeU3Values == null || probeU3Values.Length != 1 ||\n                    Single.IsNaN(probeU1Values[0]) || Single.IsInfinity(probeU1Values[0]) ||\n                    Single.IsNaN(probeU2Values[0]) || Single.IsInfinity(probeU2Values[0]) ||\n                    Single.IsNaN(probeU3Values[0]) || Single.IsInfinity(probeU3Values[0]))\n                    throw new InvalidDataException("C8.71 displacement component probe returned invalid data.");\n\n                double componentMagnitude = Math.Sqrt(\n                    probeU1Values[0] * probeU1Values[0] +\n                    probeU2Values[0] * probeU2Values[0] +\n                    probeU3Values[0] * probeU3Values[0]);\n                if (Math.Abs(componentMagnitude - probeDispValues[0]) > 1e-8)\n                    throw new InvalidDataException("C8.71 displacement components disagree with DISP/ALL at the qualified node.");\n\n                FeNode undeformedProbeNode = controller.CurrentResult.UndeformedNodes[verifiedDispNode];\n                FeNode trueScaleProbeNode = controller.GetScaledNode(1f, verifiedDispNode);\n                const float qualifiedUserScale = 10f;\n                FeNode userScaleProbeNode = controller.GetScaledNode(qualifiedUserScale, verifiedDispNode);\n                double[] x0 = undeformedProbeNode.Coor;\n                double[] xTrue = trueScaleProbeNode.Coor;\n                double[] xUser = userScaleProbeNode.Coor;\n                double[] displacementVector = new double[] { probeU1Values[0], probeU2Values[0], probeU3Values[0] };\n                double trueScaleMaxError = 0;\n                double userScaleMaxError = 0;\n                for (int i = 0; i < 3; i++)\n                {\n                    trueScaleMaxError = Math.Max(trueScaleMaxError, Math.Abs(xTrue[i] - (x0[i] + displacementVector[i])));\n                    userScaleMaxError = Math.Max(userScaleMaxError, Math.Abs(xUser[i] - (x0[i] + qualifiedUserScale * displacementVector[i])));\n                }\n                const double deformationCoordinateTolerance = 1e-7;\n                if (trueScaleMaxError > deformationCoordinateTolerance)\n                    throw new InvalidDataException("C8.71 TrueScale geometry failed Xd=X0+U. max_error=" + trueScaleMaxError);\n                if (userScaleMaxError > deformationCoordinateTolerance)\n                    throw new InvalidDataException("C8.71 user-scale geometry failed Xd=X0+scale*U. max_error=" + userScaleMaxError);\n\n                NativeScalarBarGate.Report scalarBarReport = NativeScalarBarGate.Verify(controller, min, max);\n'''
if anchor not in text:
    raise SystemExit('C8.71 Results draw anchor not found; refusing partial patch.')
text = text.replace(anchor, insert, 1)

payload_anchor = '''                    "  \\\"deformation_scale_semantics_verified\\\": false,\\n" +\n                    "  \\\"native_node_probe_verified\\\": true,\\n" +'''
payload_new = '''                    "  \\\"deformation_scale_semantics_verified\\\": true,\\n" +\n                    "  \\\"deformation_geometry_source\\\": \\\"Controller.GetScaledNode(scale,nodeId)\\\",\\n" +\n                    "  \\\"deformation_probe_node\\\": " + verifiedDispNode.ToString(CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"disp_u1_mm\\\": " + probeU1Values[0].ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"disp_u2_mm\\\": " + probeU2Values[0].ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"disp_u3_mm\\\": " + probeU3Values[0].ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"true_scale_factor\\\": 1.0,\\n" +\n                    "  \\\"true_scale_max_coordinate_error_mm\\\": " + trueScaleMaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"user_scale_factor\\\": " + qualifiedUserScale.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"user_scale_max_coordinate_error_mm\\\": " + userScaleMaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"deformation_geometry_verified\\\": true,\\n" +\n                    "  \\\"deformation_ui_scale_selector_verified\\\": false,\\n" +\n                    "  \\\"native_node_probe_verified\\\": true,\\n" +'''
if payload_anchor not in text:
    raise SystemExit('C8.70 deformation READY anchor not found; refusing partial C8.71 patch.')
text = text.replace(payload_anchor, payload_new, 1)

old_provenance = '''            provenance.Text = "SOLVER VERIFIED  |  native node probe  |  undeformed contour  |  mm-N-MPa";\n'''
new_provenance = '''            provenance.Text = "SOLVER VERIFIED  |  probe + deformation geometry  |  mm-N-MPa";\n'''
if old_provenance not in text:
    raise SystemExit('C8.70 provenance anchor not found; refusing partial C8.71 patch.')
text = text.replace(old_provenance, new_provenance, 1)

path.write_text(text, encoding='utf-8')
print(f'Patched {path} with C8.71 verified deformation geometry')
